import { Router } from 'express';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { z } from 'zod';
import { AppError } from './errors.js';
const Akun = z.object({ email: z.email().toLowerCase(), password: z.string().min(8) });
export function buatAuth({ rahasia }) {
  const pengguna = [];
  const router = Router();
  router.post('/daftar', async (req, res) => {
    const h = Akun.safeParse(req.body);
    if (!h.success) throw new AppError(400, 'VALIDASI_GAGAL', 'Email atau password tidak valid');
    if (pengguna.some((p) => p.email === h.data.email)) throw new AppError(409, 'EMAIL_SUDAH_ADA', 'Email sudah terdaftar');
    const p = { id: pengguna.length + 1, email: h.data.email, hashPassword: await bcrypt.hash(h.data.password, 10) };
    pengguna.push(p);
    res.status(201).json({ data: { id: p.id, email: p.email } });
  });
  router.post('/masuk', async (req, res) => {
    const p = pengguna.find((x) => x.email === String(req.body.email).toLowerCase());
    if (!p || !(await bcrypt.compare(String(req.body.password), p.hashPassword))) throw new AppError(401, 'LOGIN_GAGAL', 'Email atau password salah');
    res.json({ data: { token: jwt.sign({ sub: String(p.id) }, rahasia, { expiresIn: '15m' }) } });
  });
  function butuhLogin(req, res, next) {
    const [jenis, token] = (req.get('authorization') ?? '').split(' ');
    try {
      if (jenis !== 'Bearer') throw new Error();
      req.pengguna = { id: Number(jwt.verify(token, rahasia, { algorithms: ['HS256'] }).sub) };
    } catch {
      throw new AppError(401, 'PERLU_LOGIN', 'Perlu login');
    }
    next();
  }
  return { router, butuhLogin };
}
// === src/app.js ===
import express from 'express';
import { AppError } from './errors.js';
import { buatTodoRouter } from './routes/todo.js';
import { buatAuth } from './auth.js';
export function buatApp({ todoService, rahasia }) {
  const auth = buatAuth({ rahasia });
  const app = express();
  app.use(express.json());
  app.get('/health', (req, res) => res.json({ status: 'ok' }));
  app.use('/api/v1/auth', auth.router);
  app.use('/api/v1/todos', auth.butuhLogin, buatTodoRouter(todoService));
  app.use((req, res) => res.status(404).json({ error: { kode: 'JALUR_TIDAK_ADA', pesan: 'Jalur tidak ditemukan' } }));
  app.use((err, req, res, next) => {
    if (!(err instanceof AppError)) err = new AppError(500, 'KESALAHAN_SERVER', 'Terjadi kesalahan di server');
    res.status(err.status).json({ error: { kode: err.kode, pesan: err.message } });
  });
  return app;
}
