import express from 'express';
const app = express();
function butuhLogin(req, res, next) {
  if (req.get('x-token') !== 'rahasia') throw Object.assign(new Error('Perlu login'), { status: 401 });
  next();
}
app.get('/todos', butuhLogin, (req, res) => res.send('ok'));
app.use((err, req, res, next) => res.sendStatus(err.status ?? 500));
const server = app.listen(3000);
const a = await fetch('http://localhost:3000/todos');
const b = await fetch('http://localhost:3000/todos', { headers: { 'x-token': 'rahasia' } });
console.log(a.status, b.status);
